import Image from "next/image";
import Link from "next/link";

export default function Hero() {
  return (
    <section className="relative overflow-hidden bg-[#F7F2E9]">
      <div className="absolute inset-0 opacity-40">
        <div className="absolute -left-24 top-20 h-96 w-96 rounded-full border border-[#C89D4A]/20" />
        <div className="absolute -right-24 top-24 h-[28rem] w-[28rem] rounded-full border border-[#C89D4A]/20" />
      </div>

      <div className="relative mx-auto flex min-h-[760px] max-w-7xl flex-col items-center justify-center px-6 py-20 text-center">
        <Image
          src="/images/brand/fio-logo.png"
          alt="Figuring It Out compass, hourglass, book, leaves, and path logo"
          width={300}
          height={300}
          priority
          className="h-auto w-[210px] sm:w-[250px] lg:w-[285px]"
        />

        <h1 className="mt-6 font-serif text-5xl tracking-[0.06em] text-[#234531] sm:text-6xl lg:text-7xl">
          FIGURING IT OUT
          <sup className="ml-1 align-super text-sm">™</sup>
        </h1>

        <div className="my-7 flex items-center justify-center gap-3">
          <span className="h-px w-20 bg-[#C89D4A]" />
          <span className="h-2.5 w-2.5 rotate-45 bg-[#C89D4A]" />
          <span className="h-px w-20 bg-[#C89D4A]" />
        </div>

        <h2 className="max-w-3xl font-serif text-3xl leading-tight text-[#234531] sm:text-4xl lg:text-5xl">
          Choosing to keep moving
          <span className="mt-1 block italic text-[#A96F24]">
            when life doesn&apos;t make sense.
          </span>
        </h2>

        <p className="mt-6 font-serif text-xl text-[#4E4D47] sm:text-2xl">
          One philosophy. Two paths.
        </p>

        <p className="mx-auto mt-5 max-w-2xl text-base leading-8 text-[#51544E]">
          Figuring It Out™ is the lifelong practice of moving through
          uncertainty with curiosity, courage, and hope—trusting that
          understanding and confidence will grow with every step.
        </p>

        <Link
          href="#choose-your-path"
          className="mt-8 inline-flex items-center gap-3 rounded-md bg-[#234531] px-7 py-4 text-xs font-semibold uppercase tracking-[0.18em] text-white transition hover:bg-[#5A2346]"
        >
          Begin Your Journey
          <span aria-hidden="true">↓</span>
        </Link>
      </div>
    </section>
  );
}